```go
package router

type Route struct {
	Prefix  string
	Handler string
	Enabled bool
}

// Resolve returns the handler for the most specific enabled prefix.
func Resolve(routes []Route, path string) (string, bool) {
	var bestRoute *Route
	var bestLen int

	for i := range routes {
		route := &routes[i]
		if !route.Enabled {
			continue
		}

		if len(route.Prefix) <= len(path) && path[:len(route.Prefix)] == route.Prefix {
			if len(route.Prefix) > bestLen {
				bestLen = len(route.Prefix)
				bestRoute = route
			}
		}
	}

	if bestRoute != nil {
		return bestRoute.Handler, true
	}
	return "", false
}
